CREATE OR REPLACE FUNCTION private.evidence_storage_identity(bucket text, path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare identity jsonb;
begin
  if to_regclass('storage.objects') is null then return null;end if;
  execute 'select jsonb_build_object(''id'',id,''version'',version) from storage.objects where bucket_id=$1 and name=$2 and version is not null' into identity using bucket,path;
  return identity;
end $function$

CREATE OR REPLACE FUNCTION private.evidence_storage_object_exists(target_bucket text, target_path text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare present boolean;
begin
 if to_regclass('storage.objects') is null then return false;end if;
 execute 'select exists(select 1 from storage.objects where bucket_id=$1 and name=$2)' into present using target_bucket,target_path;
 return coalesce(present,false);
end $function$

CREATE OR REPLACE FUNCTION private.record_storage_attestation(kind text, eid uuid, sha text, bytes bigint, actor uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  old private.evidence_storage_attestations%rowtype;
  binding private.evidence_storage_bindings%rowtype;
  bucket text;path text;identity jsonb;
begin
  if kind='PORTAL' then select bucket_id,object_path into bucket,path from public.portal_evidence_objects where id=eid;
  elsif kind='INTERNAL' then select bucket_name,object_path into bucket,path from public.evidence_objects where id=eid;
  else raise exception 'invalid_evidence_namespace' using errcode='22023';end if;
  if to_regclass('storage.objects') is null then raise exception 'evidence_storage_object_unavailable' using errcode='55000';end if;
  execute 'select jsonb_build_object(''id'',id,''version'',version) from storage.objects where bucket_id=$1 and name=$2 and version is not null for share' into identity using bucket,path;
  if identity is null then raise exception 'evidence_storage_object_unavailable' using errcode='55000';end if;
  select * into old from private.evidence_storage_attestations where namespace=kind and evidence_id=eid;
  if found then
    if old.checksum_sha256 is distinct from sha or old.byte_size is distinct from bytes then raise exception 'evidence_attestation_conflict' using errcode='23505';end if;
  else
    insert into private.evidence_storage_attestations(namespace,evidence_id,checksum_sha256,byte_size,verified_by) values(kind,eid,sha,bytes,actor);
  end if;
  select * into binding from private.evidence_storage_bindings where namespace=kind and evidence_id=eid;
  if found then
    if jsonb_build_object('id',binding.object_id,'version',binding.object_version) is distinct from identity then raise exception 'evidence_storage_object_changed' using errcode='23505';end if;
  else
    insert into private.evidence_storage_bindings(namespace,evidence_id,object_id,object_version) values(kind,eid,(identity->>'id')::uuid,identity->>'version');
  end if;
end $function$

CREATE OR REPLACE FUNCTION public.create_evidence_upload(target_branch_id uuid, bucket_name text, object_path text, audience text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare hash text; receipt public.command_receipts%rowtype; evidence_id uuid;
begin
  if not private.has_permission(target_branch_id, 'evidence.manage') then raise exception 'forbidden' using errcode = '42501'; end if;
  if bucket_name not in ('delivery-proofs','inventory-evidence') or char_length(trim(object_path)) < 3 or audience not in ('INTERNAL','CUSTOMER') then raise exception 'invalid_evidence_upload' using errcode = '22023'; end if;
  hash := private.command_payload_hash(jsonb_build_object('branch_id', target_branch_id, 'bucket', bucket_name, 'path', trim(object_path), 'audience', audience));
  select * into receipt from public.command_receipts where command_receipts.operation_id = create_evidence_upload.operation_id;
  if found then if receipt.command_name <> 'create_evidence_upload' or receipt.payload_hash <> hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if; return receipt.result_entity_id; end if;
  insert into public.evidence_objects(branch_id, bucket_name, object_path, audience, created_by)
  values (target_branch_id, bucket_name, trim(object_path), audience, (select auth.uid())) returning id into evidence_id;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'create_evidence_upload', hash, 'evidence_object', evidence_id, now());
  return evidence_id;
end
$function$

CREATE OR REPLACE FUNCTION public.create_portal_evidence(target_context_type text, target_work_item_id uuid, target_customer_id uuid, target_mime_type text, target_byte_size bigint, operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  payload_hash text;
  receipt public.command_receipts%rowtype;
  evidence public.portal_evidence_objects%rowtype;
  extension text;
  actor_quota bigint;
begin
  if (select auth.uid()) is null then raise exception 'authentication_required' using errcode = '42501'; end if;
  if target_mime_type not in ('image/jpeg','image/png','application/pdf') or target_byte_size not between 1 and 10485760 then
    raise exception 'unsupported_evidence_file' using errcode = '22023';
  end if;
  if target_context_type = 'WORK_RESULT' then
    if target_work_item_id is null or target_customer_id is not null or not private.is_current_work_assignee(target_work_item_id) then
      raise exception 'work_evidence_forbidden' using errcode = '42501';
    end if;
  elsif target_context_type = 'PAYMENT_NOTICE' then
    if target_customer_id is null or target_work_item_id is not null or coalesce(private.portal_customer_role(target_customer_id), '') not in ('OWNER','FINANCE_CONTACT') then
      raise exception 'payment_evidence_forbidden' using errcode = '42501';
    end if;
  else
    raise exception 'unsupported_evidence_context' using errcode = '22023';
  end if;

  payload_hash := private.command_payload_hash(jsonb_build_object(
    'context', target_context_type,
    'work_item', target_work_item_id,
    'customer', target_customer_id,
    'mime', target_mime_type,
    'bytes', target_byte_size
  ));
  select * into receipt from public.command_receipts r where r.operation_id = create_portal_evidence.operation_id;
  if found then
    if receipt.command_name <> 'create_portal_evidence' or receipt.payload_hash <> payload_hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if;
    select * into evidence from public.portal_evidence_objects e where e.id = receipt.result_entity_id;
    return jsonb_build_object('id', evidence.id, 'bucket_id', evidence.bucket_id, 'object_path', evidence.object_path, 'state', evidence.object_state);
  end if;

  select coalesce(sum(coalesce(e.final_byte_size, e.declared_byte_size)), 0)
  into actor_quota
  from public.portal_evidence_objects e
  where e.uploaded_by = (select auth.uid()) and e.object_state <> 'REVOKED';
  if actor_quota + target_byte_size > 104857600 then raise exception 'portal_evidence_quota_exceeded' using errcode = '54000'; end if;

  extension := case target_mime_type when 'image/jpeg' then '.jpg' when 'image/png' then '.png' else '.pdf' end;
  evidence.id := gen_random_uuid();
  evidence.object_path := lower(target_context_type) || '/' || evidence.id::text || '-' || gen_random_uuid()::text || extension;
  insert into public.portal_evidence_objects(
    id, object_path, context_type, work_item_id, customer_id, uploaded_by, mime_type, declared_byte_size
  ) values(
    evidence.id, evidence.object_path, target_context_type, target_work_item_id, target_customer_id,
    (select auth.uid()), target_mime_type, target_byte_size
  ) returning * into evidence;
  insert into public.command_receipts
  values(operation_id, (select auth.uid()), 'create_portal_evidence', payload_hash, 'portal_evidence', evidence.id, now());
  return jsonb_build_object('id', evidence.id, 'bucket_id', evidence.bucket_id, 'object_path', evidence.object_path, 'state', evidence.object_state);
end $function$

CREATE OR REPLACE FUNCTION public.finalize_evidence_upload(target_evidence_id uuid, checksum_sha256 text, byte_size bigint, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare evidence public.evidence_objects%rowtype; hash text; receipt public.command_receipts%rowtype;
begin
  select * into evidence from public.evidence_objects where id = target_evidence_id for update;
  if evidence.id is null then raise exception 'evidence_not_found' using errcode = '23503'; end if;
  if not private.has_permission(evidence.branch_id, 'evidence.manage') then raise exception 'forbidden' using errcode = '42501'; end if;
  if checksum_sha256 !~ '^[0-9a-f]{64}$' or byte_size <= 0 then raise exception 'invalid_evidence_metadata' using errcode = '22023'; end if;
  if evidence.upload_state='PENDING' then raise exception 'storage_finalization_requires_server' using errcode='42501';end if;
  hash := private.command_payload_hash(jsonb_build_object('evidence_id', target_evidence_id, 'checksum', checksum_sha256, 'byte_size', byte_size));
  select * into receipt from public.command_receipts where command_receipts.operation_id = finalize_evidence_upload.operation_id;
  if found then if receipt.command_name <> 'finalize_evidence_upload' or receipt.payload_hash <> hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if; return receipt.result_entity_id; end if;
  if evidence.upload_state = 'VERIFIED' and (evidence.checksum_sha256 <> checksum_sha256 or evidence.byte_size <> byte_size) then raise exception 'evidence_payload_conflict' using errcode = '23505'; end if;
  update public.evidence_objects set upload_state = 'VERIFIED', checksum_sha256 = finalize_evidence_upload.checksum_sha256,
    byte_size = finalize_evidence_upload.byte_size, verified_at = coalesce(verified_at, now()) where id = target_evidence_id;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'finalize_evidence_upload', hash, 'evidence_object', target_evidence_id, now());
  return target_evidence_id;
end
$function$

CREATE OR REPLACE FUNCTION public.finalize_evidence_upload_verified(actor_uuid uuid, target_evidence_id uuid, checksum_sha256 text, byte_size bigint, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare evidence public.evidence_objects%rowtype; hash text; receipt public.command_receipts%rowtype;
begin
  select * into evidence from public.evidence_objects where id = target_evidence_id for update;
  if evidence.id is null then raise exception 'evidence_not_found' using errcode = '23503'; end if;
  if not private.evidence_actor_has_permission(actor_uuid,evidence.branch_id, 'evidence.manage') then raise exception 'forbidden' using errcode = '42501'; end if;
  if checksum_sha256 !~ '^[0-9a-f]{64}$' or byte_size <= 0 then raise exception 'invalid_evidence_metadata' using errcode = '22023'; end if;
  if actor_uuid is null or operation_id is null or checksum_sha256 is null or byte_size is null or byte_size not between 1 and 10485760 or checksum_sha256 !~ '^[0-9a-f]{64}$' then raise exception 'invalid_evidence_metadata' using errcode='22023';end if;
  if not private.evidence_storage_object_exists(evidence.bucket_name,evidence.object_path) then raise exception 'evidence_storage_object_unavailable' using errcode='55000';end if;
  hash := private.command_payload_hash(jsonb_build_object('evidence_id', target_evidence_id, 'checksum', checksum_sha256, 'byte_size', byte_size));
  select * into receipt from public.command_receipts where command_receipts.operation_id = finalize_evidence_upload_verified.operation_id;
  if found then if receipt.command_name <> 'finalize_evidence_upload' or receipt.payload_hash <> hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if; perform private.record_storage_attestation('INTERNAL',evidence.id,checksum_sha256,byte_size,actor_uuid); return receipt.result_entity_id; end if;
  if evidence.upload_state = 'VERIFIED' and (evidence.checksum_sha256 <> checksum_sha256 or evidence.byte_size <> byte_size) then raise exception 'evidence_payload_conflict' using errcode = '23505'; end if;
  perform private.record_storage_attestation('INTERNAL',evidence.id,checksum_sha256,byte_size,actor_uuid);
  update public.evidence_objects set upload_state = 'VERIFIED', checksum_sha256 = finalize_evidence_upload_verified.checksum_sha256,
    byte_size = finalize_evidence_upload_verified.byte_size, verified_at = coalesce(verified_at, now()) where id = target_evidence_id;
  insert into public.command_receipts values (operation_id, actor_uuid, 'finalize_evidence_upload', hash, 'evidence_object', target_evidence_id, now());
  insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields)
  values(actor_uuid,evidence.branch_id,'evidence.storage_verified','evidence_object',evidence.id,operation_id,array['stored_file','checksum_sha256','byte_size']);
  return target_evidence_id;
end
$function$

CREATE OR REPLACE FUNCTION public.finalize_portal_evidence(target_evidence_id uuid, target_checksum_sha256 text, target_byte_size bigint, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  evidence public.portal_evidence_objects%rowtype;
  payload_hash text;
  receipt public.command_receipts%rowtype;
begin
  select * into evidence from public.portal_evidence_objects e where e.id = target_evidence_id;
  if evidence.id is null or evidence.uploaded_by <> (select auth.uid()) or not private.portal_evidence_access(evidence.id, false) then
    raise exception 'evidence_finalize_forbidden' using errcode = '42501';
  end if;
  if target_byte_size <> evidence.declared_byte_size or target_checksum_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'evidence_integrity_mismatch' using errcode = '22023';
  end if;
  if evidence.object_state='PENDING' then raise exception 'storage_finalization_requires_server' using errcode='42501';end if;
  payload_hash := private.command_payload_hash(jsonb_build_object('evidence', target_evidence_id, 'checksum', target_checksum_sha256, 'bytes', target_byte_size));
  select * into receipt from public.command_receipts r where r.operation_id = finalize_portal_evidence.operation_id;
  if found then
    if receipt.command_name <> 'finalize_portal_evidence' or receipt.payload_hash <> payload_hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if;
    return receipt.result_entity_id;
  end if;
  if evidence.object_state = 'READY' then
    if evidence.final_byte_size <> target_byte_size or evidence.checksum_sha256 <> target_checksum_sha256 then raise exception 'evidence_already_finalized' using errcode = '23505'; end if;
  elsif evidence.object_state = 'PENDING' then
    update public.portal_evidence_objects set
      final_byte_size = target_byte_size,
      checksum_sha256 = target_checksum_sha256,
      object_state = 'READY',
      finalized_at = now()
    where id = evidence.id;
  else
    raise exception 'evidence_revoked' using errcode = '42501';
  end if;
  insert into public.command_receipts
  values(operation_id, (select auth.uid()), 'finalize_portal_evidence', payload_hash, 'portal_evidence', evidence.id, now());
  return evidence.id;
end $function$

CREATE OR REPLACE FUNCTION public.finalize_portal_evidence_verified(actor_uuid uuid, target_evidence_id uuid, target_checksum_sha256 text, target_byte_size bigint, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  evidence public.portal_evidence_objects%rowtype;
  payload_hash text;
  receipt public.command_receipts%rowtype;
begin
  select * into evidence from public.portal_evidence_objects e where e.id = target_evidence_id for update;
  if evidence.id is null or (evidence.uploaded_by <> actor_uuid and not(evidence.object_state='READY' and private.evidence_actor_has_permission(actor_uuid,coalesce((select branch_id from public.work_items where id=evidence.work_item_id),(select branch_id from public.customers where id=evidence.customer_id)),'evidence.manage'))) or not private.evidence_actor_portal_access(actor_uuid,evidence.id, false) then
    raise exception 'evidence_finalize_forbidden' using errcode = '42501';
  end if;
  if target_byte_size <> evidence.declared_byte_size or target_checksum_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'evidence_integrity_mismatch' using errcode = '22023';
  end if;
  if actor_uuid is null or operation_id is null or target_checksum_sha256 is null or target_byte_size is null or target_byte_size not between 1 and 10485760 or target_checksum_sha256 !~ '^[0-9a-f]{64}$' then raise exception 'invalid_evidence_metadata' using errcode='22023';end if;
  if not private.evidence_storage_object_exists(evidence.bucket_id,evidence.object_path) then raise exception 'evidence_storage_object_unavailable' using errcode='55000';end if;
  payload_hash := private.command_payload_hash(jsonb_build_object('evidence', target_evidence_id, 'checksum', target_checksum_sha256, 'bytes', target_byte_size));
  select * into receipt from public.command_receipts r where r.operation_id = finalize_portal_evidence_verified.operation_id;
  if found then
    if receipt.command_name <> 'finalize_portal_evidence' or receipt.payload_hash <> payload_hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if;
    perform private.record_storage_attestation('PORTAL',evidence.id,target_checksum_sha256,target_byte_size,actor_uuid);
    return receipt.result_entity_id;
  end if;
  if evidence.object_state = 'READY' then
    if evidence.final_byte_size <> target_byte_size or evidence.checksum_sha256 <> target_checksum_sha256 then raise exception 'evidence_already_finalized' using errcode = '23505'; end if;
  elsif evidence.object_state = 'PENDING' then
    update public.portal_evidence_objects set
      final_byte_size = target_byte_size,
      checksum_sha256 = target_checksum_sha256,
      object_state = 'READY',
      finalized_at = now()
    where id = evidence.id;
  else
    raise exception 'evidence_revoked' using errcode = '42501';
  end if;
  insert into public.command_receipts
  values(operation_id, actor_uuid, 'finalize_portal_evidence', payload_hash, 'portal_evidence', evidence.id, now());
  perform private.record_storage_attestation('PORTAL',evidence.id,target_checksum_sha256,target_byte_size,actor_uuid);
  insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields)
  values(actor_uuid,coalesce((select branch_id from public.work_items where id=evidence.work_item_id),(select branch_id from public.customers where id=evidence.customer_id)),'evidence.storage_verified','portal_evidence',evidence.id,operation_id,array['stored_file','checksum_sha256','byte_size']);
  return evidence.id;
end $function$

CREATE OR REPLACE FUNCTION public.get_portal_evidence_for_signing(target_evidence_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare evidence public.portal_evidence_objects%rowtype;
begin
  if not private.portal_evidence_access(target_evidence_id,true) then raise exception 'evidence_access_denied' using errcode='42501';end if;
  select * into evidence from public.portal_evidence_objects where id=target_evidence_id;
  return jsonb_build_object('id',evidence.id,'bucket_id',evidence.bucket_id,'object_path',evidence.object_path,
    'mime_type',evidence.mime_type,'checksum_sha256',evidence.checksum_sha256,'byte_size',evidence.final_byte_size);
end $function$
